CREATE TABLE `submission_users` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL, `email` text NOT NULL, `enabled` integer DEFAULT true NOT NULL, `subscription_expires_at` text, `emby_username` text, `note` text, `created_at` text NOT NULL, `updated_at` text NOT NULL);--> statement-breakpoint
CREATE UNIQUE INDEX `submission_users_email_unique` ON `submission_users` (`email`);--> statement-breakpoint
CREATE TABLE `movie_submissions` (`id` integer PRIMARY KEY AUTOINCREMENT NOT NULL, `submitter_email` text NOT NULL, `title` text NOT NULL, `release_year` integer, `media_type` text NOT NULL, `content_kind` text, `tmdb_id` integer, `tmdb_payload_json` text DEFAULT '{}' NOT NULL, `note` text, `status` text DEFAULT 'pending' NOT NULL, `converted_task_id` integer, `ip` text, `created_at` text NOT NULL, `updated_at` text NOT NULL, CHECK (`media_type` IN ('movie', 'tv')), CHECK (`content_kind` IN ('series', 'variety')), CHECK (`status` IN ('pending', 'converted', 'rejected', 'duplicate')));